<script>
  const input = document.getElementById('searchInput');
  const stories = [...document.querySelectorAll('.story')];
  const buttons = [...document.querySelectorAll('.category')];

  function filterStories(term='', type='') {
    stories.forEach(card => {
      const matchesText = !term || card.dataset.title.includes(term.toLowerCase());
      const matchesType = !type || card.dataset.type === type;
      card.classList.toggle('hidden', !(matchesText && matchesType));
    });
  }
  input.addEventListener('input', e => filterStories(e.target.value, ''));
  buttons.forEach(btn => {
    btn.addEventListener('click', () => {
      const current = btn.dataset.filter;
      const active = btn.classList.contains('active');
      buttons.forEach(b => b.classList.remove('active'));
      if(active) filterStories(input.value, '');
      else {
        btn.classList.add('active');
        filterStories(input.value, current);
      }
    });
  });
  document.querySelectorAll('.promo button').forEach(btn => {
    btn.addEventListener('click', () => {
      btn.textContent = 'THANK YOU!';
    });
  });
</script>
